755			if results[i].status != StatusCompleted {
756				t.Fatalf("goroutine %d status %s", i, results[i].status)
757			}
758		}
759		if calls != 1 {
760			t.Fatalf("action invoked %d times, want exactly 1", calls)
761		}
762	}
763	
764	type StatusResult struct{ status string }
765	
766	func eventTypes(events []*Event) []string {
767		out := make([]string, len(events))
768		for i, e := range events {
769			out[i] = e.Type
770		}
771		return out
