input.new_string:
// advanceGraph 按依赖图调度一个并发波次：
//
// 选取所有「未启动且全部前置已确认成功」的步骤并发启动。每个动作在事务外
// 运行（含其 ActionRetry 预算），返回后独立在单个 Store 事务中原子提交其
// 成功/失败状态与事件；某步成功会把其步骤名追加到确认顺序快照末尾，并
// 立即允许其下游在后续波次启动。任一步骤预算耗尽失败后不再调度新的
// （尚未启动的）步骤，但已经启动的兄弟动作都会运行到返回并提交各自结果：
// 成功的兄弟纳入补偿，失败步骤自身不补偿。ctx 在动作或等待中取消时不确认
// 当前结果、不调度新的兄弟步骤，已提交状态与既有事件保持不变。
//
// 返回 advanced=false 表示全部步骤均已确认成功（执行已进入 completed）。
func (e *Engine) advanceGraph(ctx context.Context, def Definition, g *graph, req ExecutionRequest, initial *ExecutionState) (bool, error) {
	// live 是已提交状态的进程内视图：每个成功/失败事务提交后更新，
	// 让并发动作的 SucceededSteps 与就绪判定看到此前已确认的步骤。
	live := initial

	var mu sync.Mutex
	loadLive := func() *ExecutionState {
		mu.Lock()
		defer mu.Unlock()
		return live
	}
	applyLive := func(updated *ExecutionState) {
		mu.Lock()
		live = updated
		mu.Unlock()
	}

	// wave 收集本波次内已启动步骤的最终结论；同一波次的动作并发执行。
	type outcome struct {
		idx        int
		actionErr  error // nil 表示确认成功；非 nil 为预算耗尽后的最近错误
		attempts   int
		startedAt  time.Time
		finishedAt time.Time
	}

	for {
		if err := ctx.Err(); err != nil {
			return false, err
		}
		st := loadLive()
		if st.Terminal() {
			// 上一波次的失败结果已把执行转入 compensating/compensation_failed，
			// 正向阶段到此为止。
			return true, nil
		}

		// 已确认集合：只有 succeeded 状态才算满足前置；failed 不满足，
		// 其下游保持 pending 且永不启动。
		ready := make([]int, 0)
		pending := 0
		for i := range st.Steps {
			switch st.Steps[i].Status {
			case "":
				pending++
				deps := g.deps[i]
				met := true
				for _, j := range deps {
					if st.Steps[j].Status != StepResultSucceeded {
						met = false
						break
					}
				}
				if met {
					ready = append(ready, i)
				}
			}
		}
		if pending == 0 {
			return false, nil
		}
		if len(ready) == 0 {
			// 仍有未启动步骤却没有可启动步骤：理论上只可能由失败步骤的
			// 下游造成，而失败一旦提交执行即离开 running；返回当前状态，
			// 由外层重新加载后转入补偿。
			return true, nil
		}

		results := make([]*outcome, len(ready))
		var wg sync.WaitGroup
		for slot, idx := range ready {
			idx := idx
			slot := slot
			step := def.Steps[idx]
			wg.Add(1)
			go func() {
				defer wg.Done()
				out := &outcome{idx: idx, startedAt: e.now()}
				// Attempts 记录本阶段（含预算内重试）动作的实际调用次数，
				// 随该步结果一次提交；中间失败不留计数、不追加事件。
				actionErr, attempts, err := e.runWithRetry(ctx, func() error {
					return step.Action(ctx, execView{current: loadLive, payload: req.Payload})
				}, step.ActionRetry)
				_ = err // ctx 取消时 runWithRetry 经下方 ctx.Err 统一处理
				out.attempts = attempts
				if ctx.Err() != nil {
					// 调用方取消：不解释为业务失败，不确认本动作；
					// 已提交的兄弟步骤保持不变，留待同身份重试。
					results[slot] = out
					return
				}
				out.actionErr = actionErr
				out.finishedAt = e.now()
				results[slot] = out
			}()
		}
		wg.Wait()

		if err := ctx.Err(); err != nil {
			// 等待兄弟动作期间取消：本波次全部不确认、不调度新波次，
			// 已提交状态与既有事件不变。
			return false, err
		}

		// 各动作均已返回且 ctx 未取消。按就绪下标声明顺序逐个原子提交，
		// 使事件追加顺序确定（与无并发时的声明先后直觉一致）；每个提交
		// 独立成事务，成功状态与对应事件原子可见。
		failed := false
		for _, out := range results {
			if out == nil {
				continue
			}
			committed, err := e.commitGraphOutcome(ctx, def, req, out)
			if err != nil {
				return false, err
			}
			if committed != nil {
				applyLive(committed)
				if committed.Status != StatusRunning && committed.Status != StatusCompleted {
					failed = true
				}
			}
		}
		if failed {
			// 已有失败提交，执行进入补偿阶段；已启动的兄弟动作上面均已提交。
			return true, nil
		}
	}
}

// commitGraphOutcome 把依赖图模式下单个步骤的动作结果原子提交。
// 返回提交后的最新状态副本；状态不存在或已终态（结果应丢弃）时返回 nil。
func (e *Engine) commitGraphOutcome(ctx context.Context, def Definition, req ExecutionRequest, out *struct {
	idx        int
	actionErr  error
	attempts   int
	startedAt  time.Time
	finishedAt time.Time
}) (*ExecutionState, error) {
	step := def.Steps[out.idx]
	var committed *ExecutionState
