1	package txsaga
2	
3	import (
4		"context"
5		"strings"
6		"sync"
7		"time"
8	)
9	
10	// ValidateDefinition 校验 Saga 定义，非法时返回 ErrInvalidDefinition（可 errors.Is）。
11	// 规则：名称非空、至少一个步骤、每个步骤名非空且不重复、每个步骤都提供正向
12	// 动作；任一动作/补偿的重试最大总调用次数为负、失败等待时长为负同样非法。
13	// 未配置的重试预算按最大 1 次、等待 0 处理。
14	// 使用 Step.DependsOn 声明依赖时，前置步骤必须存在、不得依赖自身、同一前置
15	// 不得重复列出，且依赖图必须无环；违反任一条同样返回 ErrInvalidDefinition。
16	func ValidateDefinition(d Definition) error {
17		if strings.TrimSpace(d.Name) == "" {
18			return ErrInvalidDefinition
19		}
20		if len(d.Steps) == 0 {
21			return ErrInvalidDefinition
22		}
23		seen := make(map[string]struct{}, len(d.Steps))
24		for _, st := range d.Steps {
25			if strings.TrimSpace(st.Name) == "" || st.Action == nil {
26				return ErrInvalidDefinition
27			}
28			if _, dup := seen[st.Name]; dup {
29				return ErrInvalidDefinition
30			}
31			if st.ActionRetry.MaxAttempts < 0 || st.ActionRetry.RetryWait < 0 ||
32				st.CompensateRetry.MaxAttempts < 0 || st.CompensateRetry.RetryWait < 0 {
33				return ErrInvalidDefinition
34			}
35			seen[st.Name] = struct{}{}
36		}
37		if _, err := buildGraph(d); err != nil {
38			return err
39		}
40		return nil
41	}
42	
43	// graph 是归一化后的前置依赖图：deps[i] 为步骤 i 的全部前置步骤下标。
44	type graph struct {
45		deps [][]int
46	}
47	
48	// buildGraph 构建并校验依赖图。任一步骤声明了前置即进入依赖图模式；
49	// 全部步骤都没有前置时返回 nil 图，编排退化为顺序模式。
50	// 未知依赖、自依赖、重复前置或存在环均返回 ErrInvalidDefinition。
51	func buildGraph(def Definition) (*graph, error) {
52		index := make(map[string]int, len(def.Steps))
53		for i, s := range def.Steps {
54			index[s.Name] = i
55		}
56		g := &graph{deps: make([][]int, len(def.Steps))}
57		hasEdges := false
58		for i, s := range def.Steps {
59			if len(s.DependsOn) == 0 {
60				continue
61			}
62			hasEdges = true
63			listed := make(map[int]struct{}, len(s.DependsOn))
64			for _, depName := range s.DependsOn {
65				j, ok := index[depName]
66				if !ok || j == i {
67					// 前置指向不存在的步骤，或步骤把自己列为前置。
68					return nil, ErrInvalidDefinition
69				}
70				if _, dup := listed[j]; dup {
71					// 同一前置被重复列出（按步骤名判定）。
72					return nil, ErrInvalidDefinition
73				}
74				listed[j] = struct{}{}
75				g.deps[i] = append(g.deps[i], j)
76			}
77		}
78		if !hasEdges {
79			return nil, nil
80		}
81		if g.hasCycle() {
82			return nil, ErrInvalidDefinition
83		}
84		return g, nil
85	}
86	
87	// hasCycle 以三色 DFS 判定依赖图中是否存在环。
88	func (g *graph) hasCycle() bool {
89		const (
90			white = 0 // 尚未访问
91			gray  = 1 // 在当前 DFS 路径上
92			black = 2 // 已完全展开
93		)
94		color := make([]byte, len(g.deps))
95		var visit func(i int) bool
96		visit = func(i int) bool {
97			color[i] = gray
98			for _, j := range g.deps[i] {
99				if color[j] == gray {
100					return true // 回到当前路径上的节点，成环
101				}
102				if color[j] == white && visit(j) {
103					return true
104				}
105			}
106			color[i] = black
107			return false
108		}
109		for i := range g.deps {
110			if color[i] == white && visit(i) {
111				return true
112			}
113		}
114		return false
115	}
116	
117	func stepIndex(def Definition) map[string]int {
118		idx := make(map[string]int, len(def.Steps))
119		for i, s := range def.Steps {
120			idx[s.Name] = i
121		}
122		return idx
123	}
