125	// Engine 在给定 Store 上执行 Saga。零值不可用，请用 NewEngine 创建。
126	type Engine struct {
127		store Store
128	
129		// 同执行身份的进程内串行化，避免并发调用重复进入同一未确认动作。
130		locksMu sync.Mutex
131		locks   map[string]*sync.Mutex
132	
133		// now 为可注入时钟；生产使用 time.Now。
134		now func() time.Time
135	}
136	
137	// NewEngine 创建基于 store 的编排引擎。
138	func NewEngine(store Store) *Engine {
139		return &Engine{store: store, locks: make(map[string]*sync.Mutex), now: time.Now}
140	}
141	
142	func (e *Engine) identityLock(businessKey, idempotencyKey string) *sync.Mutex {
143		key := businessKey + "\x00" + idempotencyKey
144		e.locksMu.Lock()
145		m, ok := e.locks[key]
146		if !ok {
147			m = &sync.Mutex{}
148			e.locks[key] = m
149		}
150		e.locksMu.Unlock()
151		return m
152	}
