		t.Fatalf("status=%s", res.Status)
	}
	var b StepOutcome
	for _, so := range res.Steps {
		if so.Name == "b" {
			b = so
		}
	}
	if b.Attempts != 3 {
		t.Fatalf("b attempts=%d want 3", b.Attempts)
	}
	events, _ := store.ClaimPendingEvents(context.Background(), 100)
	// started -> a succeeded -> b succeeded -> completed：中间失败不追加事件。
	want := []string{
