func TestGraphIndependentStepsRunConcurrently(t *testing.T) {
	store := NewMemoryStore()
	eng := NewEngine(store)
	h := newGraphHarness()

	releaseB := make(chan struct{})
	releaseC := make(chan struct{})
	bStarted := make(chan struct{})
	cStarted := make(chan struct{})
	var bOnce, cOnce sync.Once
	def := diamondDef(h, map[string]chan struct{}{}, "")
	// 为 b、c 安装闸门以观察并发，并在确认进入后回报启动。
	for i := range def.Steps {
		name := def.Steps[i].Name
		var gate, started chan struct{}
		switch name {
		case "b":
			gate, started = releaseB, bStarted
		case "c":
			gate, started = releaseC, cStarted
		}
		if gate == nil {
			continue
		}
		def.Steps[i].Action = func(_ context.Context, _ ExecutionView) error {
			h.enter(name)
			startedOnce := &bOnce
			sig := bStarted
			if name == "c" {
				startedOnce = &cOnce
				sig = cStarted
			}
			startedOnce.Do(func() { close(sig) })
			<-gate
			h.leave(name)
			return nil
		}
	}

	done := make(chan Result)
	go func() {
		res, err := eng.Execute(context.Background(), def, ExecutionRequest{
			BusinessKey: "dag-1", IdempotencyKey: "req-1",
		})
		if err != nil {
			done <- Result{}
			panic(err)
		}
		done <- res
	}()

	select {
	case <-bStarted:
	case <-time.After(2 * time.Second):
		t.Fatal("b never started")
	}
	select {
	case <-cStarted:
	case <-time.After(2 * time.Second):
		t.Fatal("c never started (b and c must run concurrently)")
	}
	close(releaseB)
	close(releaseC)

	res := <-done
	if res.Status != StatusCompleted || !res.Terminal {
		t.Fatalf("status=%s terminal=%v", res.Status, res.Terminal)
	}
	if !h.overlap() {
		t.Fatal("expected b and c to overlap in time")
	}
	if h.maxCon < 2 {
		t.Fatalf("max concurrency=%d, want >=2", h.maxCon)
	}
	// 声明顺序的结果视图不变。
	if names := stepNames(res.Steps); fmt.Sprint(names) != "[a b c d]" {
		t.Fatalf("step order = %v", names)
	}
	// d 只能在 b、c 确认后启动：d 的调用排在 b、c 之后。
	order := callOrder(t, store)
	_ = order
}

